  if(step===0){ h+='<div class="obhead">'+back+'<div class="eyebrow">Step 1 of 8</div></div>'+logoMark(72)+'<h1 class="obtitle">What should we call you?</h1><p class="obsub">Your crew sees this.</p><input type="text" id="ob-name" value="'+esc(P.name)+'" placeholder="First name" autocomplete="given-name" class="obinput">'; }
  else if(step===1){ var grps=[["Military","FORCE, BMQ, selection, rucking","sim"],["Running","5K to marathon, cycling, engine","cond"],["Strength and body","Strong, lean, over 40, postpartum","lift"],["Everyday","The habit, the desk","warm"]]; var cg=SETUP.grp;
    if(!cg){ h+='<div class="obhead">'+back+'<div class="eyebrow">Step 2 of 8</div></div><h1 class="obtitle">Which one is you?</h1><p class="obsub">Pick a lane. You\'ll choose the exact program next.</p><div class="obcards">'+grps.map(function(g){ return '<button class="obcard" data-grp="'+esc(g[0])+'">'+ico(g[2])+'<div><b>'+esc(g[0])+'</b><span class="d">'+esc(g[1])+'</span></div></button>'; }).join("")+'</div>'; }
    else { var list=GOALS.filter(function(x){return x.grp===cg;}); h+='<div class="obhead">'+back+'<div class="eyebrow">Step 2 of 8 · '+esc(cg)+'</div></div><h1 class="obtitle">What are you here for?</h1><p class="obsub">This builds your program. You can change any day of it later.</p><div class="obcards">'+list.map(function(x){ return '<button class="obcard '+(P.goal===x.id?"on":"")+'" data-goal="'+x.id+'">'+ico(x.ico)+'<div><b>'+esc(x.n)+'</b><span class="tag">'+esc(x.tag)+'</span><span class="d">'+esc(x.d)+'</span></div></button>'; }).join("")+'</div><button class="btn quiet" id="ob-othergrp" style="margin-top:4px">Other lanes</button>'; } }
  else if(step===2){ h+='<div class="obhead">'+back+'<div class="eyebrow">Step 3 of 8</div></div><h1 class="obtitle">How many days a week?</h1><p class="obsub">'+(P.goal==="force"?"Six is the full program. Fewer still works; the sim stays on Saturday.":P.goal==="rebuild"?"Three or four is plenty to start.":"Pick what you\'ll actually do, not what you wish you\'d do.")+'</p><div class="obgrid">'+[3,4,5,6].map(function(n){ var okd=g.days.indexOf(n)>=0; return '<button class="obopt '+(P.days===n?"on":"")+'" data-days="'+n+'"'+(okd?"":" disabled")+'><b>'+n+'</b><span>'+(okd?"days":"n/a")+'</span></button>'; }).join("")+'</div>'+(g.weeks?'<p class="obsub">'+g.weeks+'-week program. The last week is '+(P.goal==="sof"?"selection":"race")+' week.</p>':''); }
  else if(step===3){ h+='<div class="obhead">'+back+'<div class="eyebrow">Step 4 of 8</div></div><h1 class="obtitle">Minutes per session?</h1><p class="obsub">Warm-up and cool-down included. Sets get trimmed to fit.</p><div class="obgrid three">'+[20,30,45].map(function(n){ return '<button class="obopt '+(P.mins===n?"on":"")+'" data-mins="'+n+'"><b>'+n+'</b><span>min</span></button>'; }).join("")+'</div>'; }
  else if(step===4){ h+='<div class="obhead">'+back+'<div class="eyebrow">Step 5 of 8</div></div><h1 class="obtitle">Where do you train?</h1><div class="obgrid three">'+[["home","Home"],["gym","Gym"],["outside","Outside"]].map(function(x){ return '<button class="obopt '+(P.place===x[0]?"on":"")+'" data-place="'+x[0]+'"><b style="font-size:1.1rem">'+x[1]+'</b></button>'; }).join("")+'</div><p class="obsub" style="margin-top:18px">Tap the kit you have'+(P.place==="gym"?" (we ticked the usual gym kit)":"")+'. No kit is fine.</p><div class="chips">'+KIT.map(function(k){return '<button class="chip '+(P.kit.indexOf(k[0])>=0?"on":"")+'" data-kit="'+k[0]+'">'+esc(k[1])+'</button>';}).join("")+'</div>'; }
