  el.querySelectorAll("[data-goal]").forEach(function(b){ b.addEventListener("click",function(){ P.goal=b.dataset.goal; var gg=goalOf(P.goal); if(gg.days.indexOf(P.days)<0) P.days=gg.days[0]; if(P.goal==="metcon"){ P.mins=Math.max(P.mins,45); } if(P.goal==="bmq"){ P.mins=Math.max(P.mins,30); if(P.kit.indexOf("pullup")<0) P.kit.push("pullup"); } if(P.goal==="ruck"){ P.mins=Math.max(P.mins,45); ["vest","sandbag"].forEach(function(k){ if(P.kit.indexOf(k)<0) P.kit.push(k); }); } if(P.goal==="cycle"){ if(P.kit.indexOf("bike")<0) P.kit.push("bike"); P.mins=Math.max(P.mins,45); } if(P.goal==="desk"){ P.mins=20; } if(P.goal==="sof"){ P.mins=45; ["sandbag","vest","pullup"].forEach(function(k){ if(P.kit.indexOf(k)<0) P.kit.push(k); }); } if(["c25k","run10k","half","marathon"].indexOf(P.goal)>=0&&P.mins<30) P.mins=30; if(P.goal==="force"){ if(P.kit.indexOf("sandbag")<0) P.kit.push("sandbag"); P.days=Math.max(P.days,5); P.mins=Math.max(P.mins,30); } if(P.goal==="rebuild"){ P.days=Math.min(P.days,4); P.mins=Math.min(P.mins,30); } if(P.goal==="habit"){ P.mins=20; P.days=6; } buzz(8); go(2); }); });
