function evoNumber(){ return Object.keys(S.workouts).length+1; }
function greeting(){ var h=new Date().getHours(); return h<5?"Early.":h<12?"Good morning":h<17?"Afternoon":"Evening"; }
function animate(el){ if(!el) return; var reduce=false; try{ reduce=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches; }catch(e){}
  el.querySelectorAll("[data-count]").forEach(function(n){ var to=+n.dataset.count; if(reduce||!to){ n.textContent=to; return; } var t0=null; var dur=600; var step=function(ts){ if(!t0) t0=ts; var p=Math.min(1,(ts-t0)/dur); p=1-Math.pow(1-p,3); n.textContent=Math.round(to*p); if(p<1) requestAnimationFrame(step); }; requestAnimationFrame(step); }); }
function weekReview(t){ var mon=new Date(t); mon.setDate(t.getDate()-6); var done=0,rd=0,sched=0; for(var i=0;i<7;i++){ var d=new Date(mon); d.setDate(mon.getDate()+i); if(planFor(d).kind!=="rest"){ sched++; if(dayComplete(d)) done++; } if(routineComplete(d)) rd++; }
  var w=weekOf(t); var grade= done>=sched?"Clean week.":done>=sched-1?"Solid. One slipped.":done>=sched-2?"Two missed. Fix them before they become the pattern.":"The routine's the problem, not the program.";
  return '<div class="card hi stack"><div class="eyebrow">Week '+w+' review</div><h2>'+esc(grade)+'</h2><div class="stats"><div class="stat"><div class="v">'+done+'/'+sched+'</div><div class="l">Evolutions</div></div><div class="stat"><div class="v">'+rd+'/7</div><div class="l">Routine</div></div><div class="stat"><div class="v">'+longestStreak()+'</div><div class="l">Best streak</div></div></div></div>'; }

