  var el=$("wo"); var s=trainStreak(); var generated=(S.plan.days[t.getDay()]||{}).type!=="custom"; var adaptive=(kind==="lift"||kind==="bike")&&generated;
  el.innerHTML='<div class="top"><div class="eyebrow">'+esc(W.plan.title)+'</div></div><div class="mid"><div class="done-wrap pop"><div class="phase work">Evolution secured</div><div class="huge">'+mmss(sec)+'</div><div class="sub">on the clock</div><div class="stats" style="width:100%;max-width:360px"><div class="stat"><div class="v">'+s+'</div><div class="l">Day streak</div></div><div class="stat"><div class="v">'+Object.keys(S.workouts).length+'</div><div class="l">Secured</div></div><div class="stat"><div class="v">'+(tpl()==="force"?daysOut():longestStreak())+'</div><div class="l">'+(tpl()==="force"?"Days out":"Best streak")+'</div></div></div>'+(adaptive?'<div class="stack" style="width:100%;max-width:360px"><div class="eyebrow">How was it?</div><div class="rate"><button class="btn quiet" data-rate="1">Easy</button><button class="btn quiet" data-rate="2">Right</button><button class="btn quiet" data-rate="3">Too hard</button></div><div class="sub" id="rate-msg" style="min-height:1.4em"></div></div>':'<div class="sub" style="max-width:32ch">'+esc(doneLine(s))+'</div>')+'</div></div><div class="acts"><button class="btn big" id="wo-close">Secure</button></div>';
  el.querySelectorAll("[data-rate]").forEach(function(b){ b.addEventListener("click",function(){ el.querySelectorAll("[data-rate]").forEach(function(x){x.classList.remove("sel");}); b.classList.add("sel"); var m=rate(kind,k,+b.dataset.rate); el.querySelector("#rate-msg").textContent=m||doneLine(s); }); });
