var MEASK=[["waist","Waist"],["chest","Chest"],["hips","Hips"],["arm","Arm"],["thigh","Thigh"]];
function cmOut(cm){ return isLb()?Math.round(cm/2.54*10)/10:Math.round(cm*10)/10; } function cmIn(v){ return isLb()?Math.round(v*2.54*10)/10:+v; } function LU(){ return isLb()?"in":"cm"; }
function photosGet(){ try{ return JSON.parse(localStorage.getItem("fp.photos")||"[]"); }catch(e){ return []; } }
function photosSet(p){ try{ localStorage.setItem("fp.photos",JSON.stringify(p)); }catch(e){ toast("Photo storage is full. Delete an older one."); } }
function measCard(){ var last=S.meas.length?S.meas[S.meas.length-1]:null; var first=S.meas.length?S.meas[0]:null; var ph=photosGet();
  var h='<details class="logfold"><summary>Measurements and photos <span class="sub" style="font-weight:400">· '+(last?esc(last.date.slice(5)):"none yet")+'</span></summary><div class="body">';
  h+='<div class="mgrid">'+MEASK.map(function(m){ var v=last&&last[m[0]]; var d0=first&&first[m[0]]&&v?cmOut(v-first[m[0]]):null; return '<div class="field"><label>'+m[1]+(v?' <span class="mono" style="color:var(--accent)">'+cmOut(v)+'</span>':'')+(d0!==null&&d0!==0?' <span class="sub mono">'+(d0>0?"+":"")+d0+'</span>':'')+'</label><input type="number" inputmode="decimal" step="0.1" data-meas="'+m[0]+'" placeholder="'+LU()+'"></div>'; }).join("")+'</div><button class="btn quiet" id="meas-save">Log measurements</button>';
  h+='<div class="row" style="margin-top:8px"><div class="eyebrow">Progress photos</div><label class="mini">Add photo<input type="file" id="ph-add" accept="image/*" capture="user" hidden></label></div><div class="sub">Same spot, same light, same pose. Once a month is plenty. Photos stay on this phone only.</div>'+(ph.length?'<div class="phrow">'+ph.slice().reverse().map(function(p,i){ return '<figure><img src="'+p.src+'" alt=""><figcaption>'+esc(p.date.slice(2))+'<button class="phdel" data-phdel="'+(ph.length-1-i)+'">×</button></figcaption></figure>'; }).join("")+'</div>':'');
  return h+'</div></details>'; }
function bindMeas(el){ var ms=el.querySelector("#meas-save"); if(!ms) return; ms.addEventListener("click",function(){ var k=iso(today()); var rec={date:k}; var any=false; el.querySelectorAll("[data-meas]").forEach(function(i){ if(i.value){ rec[i.dataset.meas]=cmIn(parseFloat(i.value)); any=true; } }); if(!any) return; var prev=S.meas.filter(function(x){return x.date===k;})[0]; if(prev) Object.keys(rec).forEach(function(kk){ prev[kk]=rec[kk]; }); else S.meas.push(rec); save(); toast("Logged"); renderMe(); });
  var pa=el.querySelector("#ph-add"); if(pa) pa.addEventListener("change",function(e){ var f=e.target.files&&e.target.files[0]; if(!f) return; var img=new Image(); var url=URL.createObjectURL(f); img.onload=function(){ var c=document.createElement("canvas"); var s=Math.min(1,720/Math.max(img.width,img.height)); c.width=Math.round(img.width*s); c.height=Math.round(img.height*s); c.getContext("2d").drawImage(img,0,0,c.width,c.height); var src=c.toDataURL("image/jpeg",0.72); var ph=photosGet(); ph.push({date:iso(today()),src:src}); if(ph.length>24) ph.shift(); photosSet(ph); URL.revokeObjectURL(url); toast("Photo saved"); renderMe(); }; img.src=url; });
  el.querySelectorAll("[data-phdel]").forEach(function(b){ b.addEventListener("click",function(){ var ph=photosGet(); ph.splice(+b.dataset.phdel,1); photosSet(ph); renderMe(); }); }); }
// ================= BADGES =================
var BADGES=[
 {id:"first",n:"First evolution",d:"Secured one.",f:function(){ return Object.keys(S.workouts).length>=1; }},
 {id:"s7",n:"Seven straight",d:"7-day streak.",f:function(){ return longestStreak()>=7; }},
 {id:"s30",n:"The month",d:"30-day streak.",f:function(){ return longestStreak()>=30; }},
 {id:"s100",n:"Hundred",d:"100-day streak.",f:function(){ return longestStreak()>=100; }},
 {id:"e10",n:"Ten secured",d:"10 evolutions.",f:function(){ return Object.keys(S.workouts).length>=10; }},
 {id:"e50",n:"Fifty secured",d:"50 evolutions.",f:function(){ return Object.keys(S.workouts).length>=50; }},
 {id:"e100",n:"Century",d:"100 evolutions.",f:function(){ return Object.keys(S.workouts).length>=100; }},
 {id:"pr",n:"First PR",d:"Beat your own number.",f:function(){ return Object.keys(S.pr.ex||{}).length>=1; }},
 {id:"r30",n:"Routine · 30",d:"Morning routine locked in 30 days.",f:function(){ return Object.keys(S.routine).filter(function(k){ return routineComplete(fromIso(k)); }).length>=30; }},
 {id:"k5",n:"5K",d:"Tracked 5 km in one go.",f:function(){ return Object.keys(S.routes).some(function(k){ return S.routes[k].km>=5; }); }},
 {id:"k10",n:"10K",d:"Tracked 10 km in one go.",f:function(){ return Object.keys(S.routes).some(function(k){ return S.routes[k].km>=10; }); }},
 {id:"half",n:"Half",d:"Tracked 21.1 km.",f:function(){ return Object.keys(S.routes).some(function(k){ return S.routes[k].km>=21.1; }); }},
 {id:"ruck20",n:"20 under load",d:"A 20 km ruck.",f:function(){ return !!(S.pr.dist&&S.pr.dist.ruck>=20); }},
 {id:"murph",n:"Murph",d:"Did the whole thing.",f:function(){ return !!(S.wods.Murph&&S.wods.Murph.length); }},
 {id:"bench",n:"Benchmarked",d:"Logged five benchmark WODs.",f:function(){ return Object.keys(S.wods).length>=5; }},
 {id:"sim",n:"Sim under standard",d:"All four FORCE stations under the standard.",f:function(){ return S.sims.some(function(s){ return secs(s.rush)!==null&&secs(s.rush)<=STD.rush&&secs(s.lift)!==null&&secs(s.lift)<=STD.lift&&secs(s.shut)!==null&&secs(s.shut)<=STD.shut&&s.drag; }); }},
 {id:"ton",n:"Ten tonnes",d:"10,000 kg moved in one evolution.",f:function(){ return Object.keys(S.workouts).some(function(k){ return (S.workouts[k].vol||0)>=10000; }); }},
 {id:"crew",n:"Crew",d:"Started or joined a crew.",f:function(){ return !!(S.badges&&S.badges._crew); }}
];
function checkBadges(){ try{ var newly=[]; BADGES.forEach(function(b){ if(S.badges[b.id]) return; var ok=false; try{ ok=b.f(); }catch(e){} if(ok){ S.badges[b.id]=iso(today()); newly.push(b); } }); if(newly.length){ save(); setTimeout(function(){ toast("Badge: "+newly.map(function(b){return b.n;}).join(", ")); buzz([40,30,40]); },900); newly.forEach(function(b){ logEvent("badge","earned the "+b.n+" badge"); }); } }catch(e){} }
// ================= EXERCISE HISTORY =================
