var TRK=null;
function haversine(a,b){ var R=6371000, toR=Math.PI/180; var dLat=(b.lat-a.lat)*toR, dLon=(b.lon-a.lon)*toR; var x=Math.sin(dLat/2)*Math.sin(dLat/2)+Math.cos(a.lat*toR)*Math.cos(b.lat*toR)*Math.sin(dLon/2)*Math.sin(dLon/2); return 2*R*Math.asin(Math.sqrt(x)); }
