var LEAF=null, MAPS={};
function loadLeaflet(cb){ if(window.L){ cb(); return; } if(LEAF){ LEAF.push(cb); return; } LEAF=[cb]; var css=document.createElement("link"); css.rel="stylesheet"; css.href="https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css"; document.head.appendChild(css); var s=document.createElement("script"); s.src="https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js"; s.onload=function(){ var q=LEAF; LEAF=null; q.forEach(function(f){ f(); }); }; s.onerror=function(){ var q=LEAF; LEAF=null; q.forEach(function(f){ f(true); }); }; document.head.appendChild(s); }
