function gpxOf(k){ var rt=S.routes[k]; if(!rt) return ""; var t0=new Date(k+"T06:00:00"); var step=rt.pts.length>1?rt.sec/(rt.pts.length-1):0; return '<?xml version="1.0" encoding="UTF-8"?>\n<gpx version="1.1" creator="Evolution" xmlns="http://www.topografix.com/GPX/1/1"><trk><name>Evolution '+k+'</name><trkseg>'+rt.pts.map(function(p,i){ return '<trkpt lat="'+p[0]+'" lon="'+p[1]+'"><time>'+new Date(t0.getTime()+i*step*1000).toISOString()+'</time></trkpt>'; }).join("")+'</trkseg></trk></gpx>'; }
function importGPX(text){ var m=text.match(/<trkpt[^>]*lat="([\-\d.]+)"[^>]*lon="([\-\d.]+)"/g)||[]; if(m.length<2) return 0; var pts=m.map(function(s){ var a=s.match(/lat="([\-\d.]+)"/), b=s.match(/lon="([\-\d.]+)"/); return [parseFloat(a[1]),parseFloat(b[1])]; }); var times=text.match(/<time>([^<]+)<\/time>/g)||[]; var d=times.length?new Date(times[0].replace(/<\/?time>/g,"")):today(); var k=iso(d); var dist=0; for(var i=1;i<pts.length;i++) dist+=haversine({lat:pts[i-1][0],lon:pts[i-1][1]},{lat:pts[i][0],lon:pts[i][1]}); var sec=times.length>1?Math.round((new Date(times[times.length-1].replace(/<\/?time>/g,""))-new Date(times[0].replace(/<\/?time>/g,"")))/1000):0; S.routes[k]={km:Math.round(dist/10)/100,sec:sec,gain:0,pts:pts.filter(function(x,i){return i%3===0||i===pts.length-1;})}; if(!S.workouts[k]) S.workouts[k]={sec:sec,kind:"bike",at:"",imported:true}; save(); return pts.length; }
