function exportCSV(){ var rows=[["date","exercise","set","kg","reps","seconds"]]; Object.keys(S.exlog).forEach(function(ex){ S.exlog[ex].forEach(function(e){ e.sets.forEach(function(s,i){ rows.push([e.date,EX[ex]?EX[ex].n:ex,i+1,s.w===null||s.w===undefined?"":s.w,s.r||"",s.sec||""]); }); }); }); rows.sort(function(a,b){ return a[0]<b[0]?-1:a[0]>b[0]?1:0; }); var csv=rows.map(function(r){ return r.map(function(v){ return /[",\n]/.test(String(v))?'"'+String(v).replace(/"/g,'""')+'"':v; }).join(","); }).join("\n"); shareOrDownload("evolution-sets-"+iso(today())+".csv",csv,"text/csv"); }
function parseCSV(text){ var rows=[],row=[],cur="",q=false; for(var i=0;i<text.length;i++){ var c=text[i]; if(q){ if(c==='"'){ if(text[i+1]==='"'){ cur+='"'; i++; } else q=false; } else cur+=c; } else if(c==='"') q=true; else if(c===","||c===";"){ row.push(cur); cur=""; } else if(c==="\n"||c==="\r"){ if(c==="\r"&&text[i+1]==="\n") i++; row.push(cur); rows.push(row); row=[]; cur=""; } else cur+=c; } if(cur.length||row.length){ row.push(cur); rows.push(row); } return rows.filter(function(r){ return r.some(function(x){return x!=="";}); }); }
function matchEx(name){ var n=String(name||"").toLowerCase().replace(/\(.*?\)/g,"").replace(/[^a-z ]/g," ").replace(/\s+/g," ").trim(); if(!n) return null; var best=null,score=0; Object.keys(EX).forEach(function(id){ var en=EX[id].n.toLowerCase().replace(/[^a-z ]/g," ").replace(/\s+/g," ").trim(); if(en===n){ best=id; score=99; return; } var a=n.split(" "), b=en.split(" "); var hit=a.filter(function(w){ return w.length>2&&b.indexOf(w)>=0; }).length; var s=hit/Math.max(a.length,b.length); if(s>score&&s>=0.5){ score=s; best=id; } }); return best; }
function importStrong(text){ var rows=parseCSV(text); if(rows.length<2) return 0; var hd=rows[0].map(function(h){return h.toLowerCase().trim();}); var ix=function(names){ for(var i=0;i<names.length;i++){ var j=hd.indexOf(names[i]); if(j>=0) return j; } return -1; }; var cD=ix(["date","workout date","start_time"]), cE=ix(["exercise name","exercise","exercise_title"]), cW=ix(["weight","weight (kg)","weight_kg","kg","load"]), cR=ix(["reps","repetitions"]), cS=ix(["seconds","duration","duration_seconds","time"]); if(cD<0||cE<0) return 0; var n=0, byKey={};
  rows.slice(1).forEach(function(r){ var d=String(r[cD]||"").trim(); var m=d.match(/(\d{4})-(\d{2})-(\d{2})/); if(m) d=m[1]+"-"+m[2]+"-"+m[3]; else { var m2=d.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/); if(m2) d=m2[3]+"-"+("0"+m2[1]).slice(-2)+"-"+("0"+m2[2]).slice(-2); else { var dt=new Date(d); if(isNaN(dt)) return; d=iso(dt); } } var ex=matchEx(r[cE]); if(!ex) return; var w=cW>=0&&r[cW]!==""?parseFloat(r[cW]):null, rp=cR>=0&&r[cR]!==""?parseInt(r[cR],10):null, sc=cS>=0&&r[cS]!==""?parseFloat(r[cS]):null; if(w!==null&&isNaN(w)) w=null; if(rp!==null&&isNaN(rp)) rp=null; var key=ex+"|"+d; byKey[key]=byKey[key]||{ex:ex,date:d,sets:[]}; byKey[key].sets.push({w:w,r:rp,sec:sc||null}); n++; });
  Object.keys(byKey).forEach(function(key){ var e=byKey[key]; S.exlog[e.ex]=(S.exlog[e.ex]||[]).filter(function(x){return x.date!==e.date;}); S.exlog[e.ex].push({date:e.date,k:EX[e.ex].t,sets:e.sets}); S.exlog[e.ex].sort(function(a,b){return a.date<b.date?-1:1;}); var last=S.exlog[e.ex][S.exlog[e.ex].length-1]; S.last[e.ex]={date:last.date,sets:last.sets.map(function(s){return {w:s.w,r:s.r};})}; e.sets.forEach(function(s){ if(s.w&&s.r){ var v=e1(s.w,s.r); var pr=S.pr.ex[e.ex]; if(!pr||v>pr.e1) S.pr.ex[e.ex]={w:s.w,r:s.r,e1:v,date:e.date}; } }); if(!S.workouts[e.date]) S.workouts[e.date]={sec:0,kind:"lift",at:"",imported:true}; });
  save(); return n; }
