function renderTest(){ var el=$("v-test"); var h='<div class="top"><button class="ibtn" id="t-back" aria-label="Back"><svg viewBox="0 0 24 24"><path d="M15 5l-7 7 7 7"/></svg></button><div class="eyebrow">FORCE · '+daysOut()+' days out</div><span></span></div>';
  if(T){ h+=renderTestMode(); } else {
    h+='<div class="card hi stack"><h2>Four stations. Short breaks. All four count.</h2><div class="sub">Confirm current standards with the recruiter before test day.</div><button class="btn big" id="t-start">Run a timed sim</button></div>';
    h+='<div class="std">'+STATIONS.map(function(s){ return '<div class="r"><div><b>'+esc(s.n)+'</b><small>'+esc(s.d)+'</small><small style="color:var(--fg);margin-top:4px">'+esc(s.tip)+'</small></div><div class="t">'+(s.std?mmss(s.std):"finish")+'</div></div>'; }).join("")+'</div>';
    var sims=S.sims.slice().sort(function(a,b){return a.date<b.date?-1:1;}); h+='<div class="card stack"><div class="eyebrow">Sim times vs. the standard</div>'+(sims.length?simChart(sims):'<div class="sub">No sims yet.</div>')+simTable(sims)+'</div>';
    h+='<div class="card stack"><div class="eyebrow">Log a sim by hand</div><div class="grid2"><div class="field"><label for="s-date">Date</label><input id="s-date" type="date" value="'+iso(today())+'"></div><div class="field"><label for="s-rush">Rushes m:ss</label><input id="s-rush" type="text" inputmode="numeric" placeholder="0:48"></div><div class="field"><label for="s-lift">Lift m:ss</label><input id="s-lift" type="text" inputmode="numeric" placeholder="2:55"></div><div class="field"><label for="s-shut">Shuttles m:ss</label><input id="s-shut" type="text" inputmode="numeric" placeholder="4:40"></div></div><label class="row" style="justify-content:flex-start"><input type="checkbox" id="s-drag" checked style="width:20px;height:20px;accent-color:var(--accent)"> Drag completed without stopping</label><button class="btn" id="s-save">Save sim</button></div>'; }
  el.innerHTML=h; el.querySelector("#t-back").addEventListener("click",back);
  var b=el.querySelector("#t-start"); if(b) b.addEventListener("click",startTestMode);
  var sv=el.querySelector("#s-save"); if(sv) sv.addEventListener("click",function(){ var s={date:el.querySelector("#s-date").value,rush:el.querySelector("#s-rush").value.trim(),lift:el.querySelector("#s-lift").value.trim(),shut:el.querySelector("#s-shut").value.trim(),drag:el.querySelector("#s-drag").checked}; if(!s.rush&&!s.lift&&!s.shut) return; S.sims.push(s); save(); logEvent("sim","ran a FORCE sim: "+simVerdictShort(s)+" under standard"); toast(simVerdict(s)); renderTest(); });
  el.querySelectorAll("[data-del]").forEach(function(b){ b.addEventListener("click",function(){ var i=+b.dataset.del; if(!b.dataset.ok){ b.dataset.ok="1"; b.textContent="Sure?"; return; } S.sims.splice(i,1); save(); renderTest(); }); });
  if(T) bindTestMode(el); }
function startTestMode(){ T={i:0,res:{},run:false,t0:0,acc:0,tick:null}; beep(880,60,0.001); wake(true); show("test"); }
function renderTestMode(){ var s=STATIONS[T.i]; var h='<div class="card hi stack"><div class="row"><div class="eyebrow">Station '+(T.i+1)+' of 4</div><button class="btn quiet" id="t-x" style="padding:6px 10px">Cancel</button></div><h2>'+esc(s.n)+'</h2><div class="sub">'+esc(s.d)+'</div>';
  if(s.std){ h+='<div style="text-align:center"><div id="t-clock" class="bigclock">'+mmss1(T.acc)+'</div><div class="sub">standard '+mmss(s.std)+'</div></div><div class="row"><button class="btn" id="t-go" style="flex:1">'+(T.run?"Stop":"Start")+'</button><button class="btn quiet" id="t-reset" style="flex:1">Reset</button></div><button class="btn big" id="t-next" '+(T.run||T.acc===0?"disabled":"")+'>Save &amp; next station</button>'; }
  else { h+='<div class="sub">'+esc(s.tip)+'</div><div class="row"><button class="btn" id="t-drag-y" style="flex:1">Completed</button><button class="btn danger" id="t-drag-n" style="flex:1">Had to stop</button></div>'; }
  h+='</div><div class="std">'+STATIONS.map(function(st,i){ var r=T.res[st.id]; var done=r!==undefined; return '<div class="r" style="'+(i===T.i?"background:var(--accent-soft)":"")+'"><div><b>'+esc(st.n)+'</b></div><div class="t" style="color:'+(done?(st.std?(r<=st.std?"var(--accent)":"var(--bad)"):(r?"var(--accent)":"var(--bad)")):"var(--muted)")+'">'+(done?(st.std?mmss(r):(r?"✓":"✗")):"—")+'</div></div>'; }).join("")+'</div>'; return h; }
function bindTestMode(el){ var s=STATIONS[T.i]; el.querySelector("#t-x").addEventListener("click",function(){ if(T.tick) clearInterval(T.tick); T=null; wake(false); renderTest(); });
  if(s.std){ el.querySelector("#t-go").addEventListener("click",function(){ if(!T.run){ T.run=true; T.t0=Date.now(); beep(1046,200,0.3); T.tick=setInterval(function(){ var c=el.querySelector("#t-clock"); if(c) c.textContent=mmss1(T.acc+Date.now()-T.t0); },100); } else { T.acc+=Date.now()-T.t0; T.run=false; clearInterval(T.tick); beep(523,200,0.3); } renderTest(); });
    el.querySelector("#t-reset").addEventListener("click",function(){ T.acc=0; T.run=false; if(T.tick) clearInterval(T.tick); renderTest(); });
    el.querySelector("#t-next").addEventListener("click",function(){ T.res[s.id]=Math.round(T.acc/100)/10; T.acc=0; T.i++; renderTest(); }); }
  else { var fin=function(ok){ T.res.drag=ok; var sim={date:iso(today()),rush:T.res.rush,lift:T.res.lift,shut:T.res.shut,drag:ok}; S.sims.push(sim); var k=iso(today()); if(planFor(today()).kind==="sim") S.workouts[k]={sec:0,kind:"sim",at:hhmm()}; save(); logEvent("sim","ran a FORCE sim: "+simVerdictShort(sim)+" under standard"); T=null; wake(false); beep(784,150,0.3); setTimeout(function(){beep(1046,300,0.3);},160); toast(simVerdict(sim)); renderTest(); };
    el.querySelector("#t-drag-y").addEventListener("click",function(){fin(true);}); el.querySelector("#t-drag-n").addEventListener("click",function(){fin(false);}); } }
function simVerdictShort(sim){ var ok=0; [["rush",STD.rush],["lift",STD.lift],["shut",STD.shut]].forEach(function(x){ var s=secs(sim[x[0]]); if(s!==null&&s<=x[1]) ok++; }); return (ok+(sim.drag?1:0))+"/4"; }
function simTable(sims){ if(!sims.length) return ''; var h='<div class="tscroll"><table><tr><th>Date</th><th>Rushes</th><th>Lift</th><th>Shuttles</th><th>Drag</th><th></th></tr>'; sims.slice().reverse().forEach(function(s){ var idx=S.sims.indexOf(s); h+='<tr><td>'+esc(s.date.slice(5))+'</td>'+cell(s.rush,51)+cell(s.lift,210)+cell(s.shut,321)+'<td class="'+(s.drag?"ok":"bad")+'">'+(s.drag?"✓":"✗")+'</td><td><button class="mini" data-del="'+idx+'">✕</button></td></tr>'; }); return h+'</table></div>'; }
function cell(t,limit){ var s=secs(t); if(s===null) return '<td>—</td>'; return '<td class="'+(s<=limit?"ok":"bad")+'">'+mmss(s)+'</td>'; }
function simChart(sims){ var Wd=600,Hh=240,pl=40,pr=12,pt=14,pb=28; var n=sims.length; var series=[["rush","Rushes","var(--accent)"],["lift","Lift","var(--fg)"],["shut","Shuttles","var(--muted)"]];
  var pts=series.map(function(sr){ return sims.map(function(s){ var v=secs(s[sr[0]]); return v===null?null:v/STD[sr[0]]*100; }); }); var all=[].concat.apply([],pts).filter(function(x){return x!==null;}); if(!all.length) all=[100];
  var mx=Math.max(120,Math.ceil(Math.max.apply(null,all.concat([100]))/10)*10+5); var mn=Math.min(60,Math.floor(Math.min.apply(null,all)/10)*10-5); var x=function(i){ return n===1?(pl+(Wd-pl-pr)/2):pl+i*(Wd-pl-pr)/(n-1); }, y=function(v){ return pt+(mx-v)/(mx-mn)*(Hh-pt-pb); };
  var h='<svg class="chart" viewBox="0 0 '+Wd+' '+Hh+'" role="img">'; for(var g=Math.ceil(mn/20)*20; g<=mx; g+=20){ h+='<line x1="'+pl+'" x2="'+(Wd-pr)+'" y1="'+y(g)+'" y2="'+y(g)+'" stroke="var(--line)"/><text x="'+(pl-6)+'" y="'+(y(g)+4)+'" font-size="11" text-anchor="end" fill="var(--muted)">'+g+'%</text>'; }
  h+='<line x1="'+pl+'" x2="'+(Wd-pr)+'" y1="'+y(100)+'" y2="'+y(100)+'" stroke="var(--bad)" stroke-width="2" stroke-dasharray="6 4"/><text x="'+(Wd-pr)+'" y="'+(y(100)-5)+'" font-size="11" text-anchor="end" fill="var(--bad)">standard</text>';
  series.forEach(function(sr,si){ var d="",first=true; pts[si].forEach(function(v,i){ if(v===null) return; d+=(first?"M":"L")+x(i).toFixed(1)+" "+y(v).toFixed(1)+" "; first=false; }); if(d) h+='<path d="'+d+'" fill="none" stroke="'+sr[2]+'" stroke-width="2.5" stroke-linejoin="round"/>'; pts[si].forEach(function(v,i){ if(v!==null) h+='<circle cx="'+x(i)+'" cy="'+y(v)+'" r="4" fill="'+sr[2]+'"/>'; }); });
  sims.forEach(function(s,i){ if(n<=8||i%Math.ceil(n/8)===0||i===n-1) h+='<text x="'+x(i)+'" y="'+(Hh-8)+'" font-size="11" text-anchor="middle" fill="var(--muted)">'+esc(s.date.slice(5))+'</text>'; }); var lx=pl; series.forEach(function(sr){ h+='<rect x="'+lx+'" y="'+(Hh-24)+'" width="10" height="3" fill="'+sr[2]+'"/><text x="'+(lx+14)+'" y="'+(Hh-19)+'" font-size="11" fill="var(--muted)">'+sr[1]+'</text>'; lx+=70; }); return h+'</svg>'; }

